        <el-form-item label="Test Itemandaccuratebackupitem"><el-input v-model="form.details.preparation" type="textarea" placeholder="by HospitalNotificationfillwrite, needneedcarrywhat, to whichinhandlemanageetc."/></el-form-item>
        <el-form-item label="relatedthis timesExaminationReport"><el-select v-model="form.details.reportId" clearable filterable><el-option v-for="r in reports" :key="r.id" :value="r.id" :label="`${r.recordDate} ${r.hospitalName||''} ${r.recordType||''}`"/></el-select></el-form-item>
        <el-form-item label="down timesfollow-up examinationTime"><el-date-picker v-model="form.details.nextAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="markthis timescompleteafter , AutomaticCreatedown timesappointment"/></el-form-item>
      </template>
      <template v-if="form.kind==='ORDER'">
        <el-alert title="by Clinicianprovide prescriptionfillwrite, Savenewversionthis willin take effectDatesamestepMedication Reminders. legacyversionthis keep. " :closable="false" type="info"/>
        <div class="entry-grid"><el-form-item label="Medication" required><el-select v-model="form.details.medicationId" filterable><el-option v-for="m in medications" :key="m.id" :value="m.id" :label="m.drugName"/></el-select></el-form-item><el-form-item label="changetype"><el-radio-group v-model="form.details.action"><el-radio value="CHANGE">start / adjustmedication</el-radio><el-radio value="STOP">stop medication</el-radio></el-radio-group></el-form-item><el-form-item label="take effectDate" required><el-date-picker v-model="form.details.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item v-if="form.details.action!=='STOP'" label="therapyprocessEnd Date (can leave blank) "><el-date-picker v-model="form.details.endDate" clearable value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="opentoolClinician"><el-input v-model="form.details.doctor"/></el-form-item><el-form-item label="countamountUnit"><el-input v-model="form.details.unit" placeholder="tablet / item / ml,  and InventoryUnitkeeponecause"/></el-form-item></div>
        <template v-if="form.details.action!=='STOP'"><el-form-item label="duplicatestarperiod"><el-checkbox-group v-model="days"><el-checkbox v-for="(d,i) in weekdays" :key="i" :value="String(i+1)">{{d}}</el-checkbox></el-checkbox-group></el-form-item>
          <el-form-item label="medication intakeTime and each timesdosage" required><div class="dose-list"><div v-for="(dose,i) in form.details.doses" :key="i" class="dose-row"><el-time-picker v-model="dose.time" value-format="HH:mm" format="HH:mm"/><el-input-number v-model="dose.quantity" :min="0.001" :precision="3"/><span>{{form.details.unit}}</span><el-button :disabled="form.details.doses.length===1" @click="form.details.doses.splice(i,1)">Delete</el-button></div><el-button @click="form.details.doses.push({time:'20:00',quantity:1})">increaseonetimes</el-button></div></el-form-item>
        </template>
        <el-form-item label="prescriptionoriginaltext / adjustreason"><el-input v-model="form.details.instructions" type="textarea" :rows="3"/></el-form-item>
        <el-form-item label="prescriptioncaretablet or PDF"><input type="file" accept="image/*,application/pdf" @change="attach"/><div v-for="(a,i) in form.details.attachments" :key="i"><a :href="a.dataUrl" :download="a.name">{{a.name}}</a><el-button link type="danger" @click="form.details.attachments.splice(i,1)">Remove</el-button></div></el-form-item>
        <el-checkbox v-model="form.details.confirmed">Ialready based onClinicianprescriptionverifyMedication, dosage and take effectDate</el-checkbox>
