        <el-form-item label="when timein what to do / companionfollowcondition"><el-input v-model="form.details.context" type="textarea"/></el-form-item><el-form-item label="what to do, validresultfor example what"><el-input v-model="form.details.response" type="textarea"/></el-form-item>
