        <div class="entry-grid"><el-form-item label="Please whofollow-up"><el-select v-model="form.assignedUserId" clearable><el-option v-for="m in members" :key="m.userId" :value="m.userId" :label="m.name"/></el-select></el-form-item><el-form-item label="preferredtimecomplete"><el-date-picker v-model="form.eventAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-form-item label="ReminderTime"><el-date-picker v-model="form.notifyAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item></div>
      </template>
