    <template #footer><el-button @click="$emit('update:modelValue',false)">Cancel</el-button><el-button type="primary" :loading="saving" @click="submit">Save</el-button></template>
  </el-dialog>
</template>
<script setup>
import {reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {saveCareItem} from '@/api/care'
import {localDateKey} from '@/utils/familyHealth'
const props=defineProps({modelValue:Boolean,kind:String,row:Object,patientId:[Number,String],members:{type:Array,default:()=>[]},medications:{type:Array,default:()=>[]},reports:{type:Array,default:()=>[]},appointments:{type:Array,default:()=>[]}})
const emit=defineEmits(['update:modelValue','saved'])
const form=reactive({details:{}}),saving=ref(false),days=ref([]),weekdays=['weekone','weektwo','weekthree','weekfour','weekfive','weeksix','weekDay']
const titles={APPOINTMENT:'follow-up visit / follow-up examinationschedule',ORDER:'prescription and medication regimen',SYMPTOM:'recordsymptom',QUESTION:'follow-up visitquestion',HANDOVER:'carehandover'}
watch(()=>props.modelValue,open=>{if(!open)return;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{kind:props.kind,title:'',eventAt:null,notifyAt:null,assignedUserId:null,details:{startDate:localDateKey(),endDate:null,action:'CHANGE',unit:'tablet',repeatDays:'1,2,3,4,5,6,7',doses:[{time:'08:00',quantity:1}],attachments:[],confirmed:false,severity:3,progress:'ONGOING'}},props.row?JSON.parse(JSON.stringify(props.row)):{});if(props.kind==='ORDER'){delete form.id;form.details.confirmed=false}days.value=String(form.details.repeatDays||'1,2,3,4,5,6,7').split(',');if(props.kind==='SYMPTOM'&&!form.eventAt)form.eventAt=localDateKey()+' '+new Date().toTimeString().slice(0,8)})
async function attach(e){const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){ElMessage.warning('each copyAttachmentPlease controlin 5MBtowithin');return}const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});form.details.attachments||=[];form.details.attachments.push({name:file.name,dataUrl});e.target.value=''}
async function submit(){if(!form.title.trim()){ElMessage.warning('Please fillwritetitle');return}if(['APPOINTMENT','SYMPTOM'].includes(form.kind)&&!form.eventAt){ElMessage.warning('SelectTime');return}saving.value=true;const pid=props.patientId;try{const data=JSON.parse(JSON.stringify(form));data.patientId=pid;if(data.kind==='ORDER')data.details.repeatDays=days.value.join(',');await saveCareItem(data);if(pid===props.patientId){emit('saved');emit('update:modelValue',false)}ElMessage.success('Saved successfully.')}finally{saving.value=false}}
</script>
<style scoped>.entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.care-entry :deep(.el-select),.care-entry :deep(.el-date-editor){width:100%}.dose-list{width:100%}.dose-row{display:flex;gap:10px;align-items:center;margin-bottom:10px}.dose-row :deep(.el-date-editor){width:150px}@media(max-width:600px){.entry-grid{grid-template-columns:1fr}.dose-row{flex-wrap:wrap}}</style>
